import { getT } from '@/lib/i18n';

// One badge per payment method, in a fixed order. The artwork is generated by scripts/make-payment-badges.mjs
// (uniform 256x256 rounded squares: same size, radius, optical margin and hairline for every logo).
const BADGES: { key: string; src: string }[] = [
  { key: 'BANK_BNCTL', src: '/images/payments/bank-bnctl.webp' },
  { key: 'ATM_BNCTL', src: '/images/payments/atm-p24.webp' },
  { key: 'TPAY', src: '/images/payments/tpay.webp' },
  { key: 'MOSAN', src: '/images/payments/mosan.webp' },
  { key: 'COD', src: '/images/payments/cod.webp' },
];

/**
 * "Payment methods" strip for the dark footer. Shows only the methods the shop really offers
 * (in production a method without real receiving details is hidden, so its logo must not be advertised either).
 */
export async function PaymentBadges({ methods }: { methods: { key: string; name: string }[] }) {
  const { t } = await getT();
  const offered = new Map(methods.map((m) => [m.key, m.name]));
  const items = BADGES.filter((b) => offered.has(b.key));
  if (!items.length) return null;

  return (
    <section aria-labelledby="footer-payments" className="mt-8">
      <h3 id="footer-payments" className="mb-3.5 flex items-center gap-3 text-[11px] font-semibold uppercase tracking-[0.18em] text-gold">
        <span aria-hidden="true" className="h-px w-7 bg-gold/60" />
        {t('footer.payment_title')}
      </h3>
      <ul className="grid max-w-[21rem] grid-cols-5 gap-2.5">
        {items.map((b) => {
          const name = offered.get(b.key) ?? b.key;
          return (
            <li key={b.key}>
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={b.src}
                alt={name}
                title={name}
                width={128}
                height={128}
                loading="lazy"
                decoding="async"
                className="aspect-square w-full rounded-[22.5%] shadow-[0_6px_14px_-8px_rgba(0,0,0,0.65)] transition duration-200 hover:-translate-y-0.5"
              />
            </li>
          );
        })}
      </ul>
    </section>
  );
}
